44.             {
45.                 return await base.SendAsync(request, cancellationToken).ConfigureAwait(false);
46.             }
47. 
48.             string clientId = GetClientIdentifier(request);
49.             var gate = this.clientGates.GetOrAdd(clientId, _ => new SemaphoreSlim(1, 1));
50. 
51.             if (!await gate.WaitAsync(0).ConfigureAwait(false))
52.             {
53.                 return CreateCircuitBreakerResponse(request, clientId);
54.             }
55. 
56.             try
57.             {
58.                 return await base.SendAsync(request, cancellationToken).ConfigureAwait(false);
59.             }
60.             finally
61.             {
62.                 gate.Release();
63.             }
64.         }
