         private readonly ICacheInvalidator cacheInvalidator;
         private readonly IHybridCache<ActionPlanInstance> actionPlanInstanceCache;
         private readonly AutoCacheECEResult<CloudParametersXml> cloudParametersXML;
         private readonly int actionPlanInstanceRefreshIntervalInSeconds;

         /// <summary>
         /// Initializes a new instance of the <see cref="BufferedECEClient"/> class.
         /// </summary>
         /// <param name="unbufferedClient">An instance of a normal ECE client.</param>
         /// <param name="cacheFactory">The cache factory.</param>
         /// <param name="cacheInvalidator">Cache invalidator.</param>
         /// <param name="configDict">The configuration dictionary.</param>
         /// <param name="settings">The cache settings.</param>
         public BufferedECEClient(
             IEnterpriseCloudEngineClient unbufferedClient,
             IHybridCacheFactory cacheFactory,
             ICacheInvalidator cacheInvalidator,
             Dictionary<string, string> configDict,
             BufferedECEClientSettings settings = null)
         {
             if (unbufferedClient is BufferedECEClient)
             {
                 throw new InvalidOperationException("Using this class recursively is not allowed.");
             }

             this.unbufferedClient = unbufferedClient;
             this.cacheInvalidator = cacheInvalidator;
             settings = settings ?? BufferedECEClientSettings.Default;

             this.actionPlanInstanceRefreshIntervalInSeconds = configDict.GetSetting(
                 BufferedECEClientSettings.ActionPlanInstanceRefreshIntervalParameterName,
                 BufferedECEClientSettings.DefaultActionPlanInstanceRefreshIntervalInSeconds);

             var actionPlanInstanceCacheSettings = CacheSettings.GetCacheSettings<ActionPlanInstance>(configDict);
             var actionPlanInstanceExpirationTime = actionPlanInstanceCacheSettings.IsDefault
                 ? settings.ActionPlanInstanceExpirationTime
                 : (actionPlanInstanceCacheSettings.MemoryCacheSettings.TimeToLive ?? settings.ActionPlanInstanceExpirationTime);
             this.actionPlanInstanceCache = cacheFactory.CreateCache<ActionPlanInstance>(
                 actionPlanInstanceExpirationTime,
                 actionPlanInstanceCacheSettings.BackgroundRefreshSettings.ValueFactoryTimeout);

