     using System;
     using System.Collections.Generic;
     using System.Linq;
     using System.Runtime.CompilerServices;
     using System.Threading;
     using System.Threading.Tasks;

     using Trace;

     public class CacheInvalidator : ICacheInvalidator
     {
         private readonly IHybridCacheFactory cacheFactory;

         // location
         public event EventHandler<UpdateLocationHealthCheckFinishedEventArgs> OnUpdateLocationSystemHealthCheckFinished;
         public event EventHandler<RefreshUpdateLocationEventArgs> OnRefreshUpdateLocation;

         // update
         public event EventHandler<UpdateAddedEventArgs> OnUpdateAdded;
         public event EventHandler<RefreshUpdateEventArgs> OnRefreshUpdate;
         public event EventHandler<RefreshUpdatesEventArgs> OnRefreshUpdates;

         // run
         public event EventHandler<UpdateRunAddedEventArgs> OnUpdateRunAdded;
         public event EventHandler<RefreshUpdateRunEventArgs> OnRefreshUpdateRun;

         // health check
         public event EventHandler<SystemHealthCheckStartedEventArgs> OnSystemHealthCheckStarted;
         public event EventHandler<SystemHealthCheckStatusChangedEventArgs> OnSystemHealthCheckStatusChanged;

         // action plan
         public event EventHandler<RefreshActionPlanInstanceEventArgs> OnRefreshActionPlanInstance;
         public event EventHandler<RefreshUpdateActionPlanInstancesEventArgs> OnRefreshUpdateActionPlanInstances;
         public event EventHandler<MonitorUpdateInstallationActionPlanInstanceEventArgs> OnMonitorUpdateInstallationActionPlanInstance;

         // cloud params
         public event EventHandler<RefreshCloudParametersXmlEventArgs> OnRefreshCloudParametersXml;

         // disc config
         public event EventHandler<RefreshDiscoveryConfigEventArgs> OnRefreshDiscoveryConfig;

         // feature flag
         public event EventHandler<FeatureFlagChangedEventArgs> OnFeatureFlagChanged;

         public CacheInvalidator(IHybridCacheFactory cacheFactory)
         {
             this.cacheFactory = cacheFactory;
         }

         public async Task InvalidateCache<T>(
             T value,
             Func<T, CacheKey> getCacheKey,
             CancellationToken cancel = default) where T : ICachedItem
         {
             if (value == null)
             {
                 return;
             }

             var cacheKey = getCacheKey(value);

             try
             {
                 var cache = this.cacheFactory.TryGet<T>();
                 if (cache != null)
                 {
                     await cache.SetAsync(cacheKey, value, token: cancel);
                 }
             }
             catch (Exception e)
             {
                 CacheEventLogger.CacheSetFailed(cacheKey.FullKey, e);
"}

