     using Microsoft.AzureStack.Common.Infrastructure.WebLayer.Contract;

     /// <summary>
     /// This class is used to setup the update service.
     /// </summary>
     public class UpdateServiceStartup
     {
         /// <summary>
         /// Initializes UpdateServiceStartup class.
         /// </summary>
         /// <param name="config">The HTTP configuration.</param>
          /// <param name="peerCertificateSubjects">The list of allowed calling client certificate subjects.</param>
         /// <param name="disableAuth">Disable auth, for tests.</param>
         public void UpdateServiceInitialize(
             HttpConfiguration config,
             string[] peerCertificateSubjects,
             bool disableAuth = false)
         {
             config.EnableCaseInsensitive(true);

             // Configure the formatters so we don't output XML
             config.Formatters.ConfigureDefaultResourceProviderFormatters();

             // Override the contract resolver to not convert dictionary keys to camelCase.
             config.Formatters.JsonFormatter.SerializerSettings.ContractResolver = new CamelCasePropertyNamesContractResolver()
             {
                 NamingStrategy = new CamelCaseNamingStrategy(processDictionaryKeys: false, overrideSpecifiedNames: true)
             };

             // Add custom JSON converters for Update models
             config.Formatters.JsonFormatter.SerializerSettings.Converters.Add(new UpdateJsonConverter());
             config.Formatters.JsonFormatter.SerializerSettings.Converters.Add(new UpdateRunJsonConverter());
             config.Formatters.JsonFormatter.SerializerSettings.Converters.Add(new UpdateLocationJsonConverter());
             config.Formatters.JsonFormatter.SerializerSettings.Converters.Add(new DiscoveryDiagnosticInfoJsonConverter());

             // We use a custom resolver because our controller are abstracts and would not be discovered by the default one.
             config.Services.Replace(typeof(IHttpControllerTypeResolver), new ResourceProviderHttpControllerTypeResolver());

             // We use a custom assemblies resolver to ensure all the DLLs are loaded.
             config.Services.Replace(typeof(IAssembliesResolver), new ResourceProviderAssembliesResolver("Microsoft.AzureStack.*.UpdateService.Controllers.*.dll"));

             config.Services.Replace(typeof(IHttpActionSelector), new ResourceProviderActionControllerSelector());

             // Map the HTTP attribute routes using our custom route provider to handle the resource type parameter
             config.MapHttpAttributeRoutes(new ResourceProviderDirectRouteProvider(typeof(UnauthorizedResourceControllerBase<>)));

             // Tracing handler.
             var handler = new TracingHandler();
             config.MessageHandlers.Insert(0, handler);
             config.Filters.Add(new UnhandledExceptionFilterAttribute());

             var policy = new NoRevocationCheckCertificateChainPolicy();
             var mtlsProvider = new MtlsCertificateAuthorizationProvider(peerCertificateSubjects, policy);

             // Authorization handler.
             var authHandler = disableAuth
                 ? (DelegatingHandler) new NoAuthMessageHandler()
                 : new MultiAuthMessageHandler(new IRequestAuthorizationProvider[] {
                     new CertificateRequestAuthorizationProvider(mtlsProvider)
                     });

             config.MessageHandlers.Insert(1, authHandler);

             // Per-client circuit breaker for UpdateLocation GET requests.
             config.MessageHandlers.Add(new PerClientCircuitBreakerHandler());

             config.EnsureInitialized();

             this.WebApiConfiguration = config;
         }

         /// <summary>
         /// Gets the Web API configuration.
         /// </summary>
