     using System.Web.Http.Hosting;
     using System.Web.Http.Routing;
     using System.Web.Http;

     public static class WebApiTestHelper
     {
         /// <summary>
         /// Wires up Configuration, Request, ControllerContext and ActionContext so you can
         /// call your ApiController action directly in unit tests.
         /// </summary>
         /// <typeparam name="TController">Your controller type</typeparam>
         /// <param name="controller">An instantiated controller</param>
         /// <param name="routePrefix">
         /// The value you used in [RoutePrefix("…")].
         /// Also used as the "controller" route‐value and to build the fake URL.
         /// </param>
         /// <param name="actionExpression">
         /// An expression selecting the action you intend to call.
         /// E.g. c => c.GetUpdateProgress()
         /// </param>
         public static void InitializeForTest<TController>(
             TController controller,
             string routePrefix,
             Expression<Func<TController, Task<IHttpActionResult>>> actionExpression)
             where TController : ApiController
         {
             // 1) configuration & attribute routes
             var config = new HttpConfiguration();
             config.MapHttpAttributeRoutes();

             // 2) fake request (method doesn't really matter for wiring-up)
             var request = new HttpRequestMessage(
                 HttpMethod.Get,
                 $"http://fakehost/{routePrefix}");
             request.Properties[HttpPropertyKeys.HttpConfigurationKey] = config;

