             var route = new HttpRoute();
             var routeData = new HttpRouteData(
                 route,
                 new HttpRouteValueDictionary { ["controller"] = routePrefix });
             request.Properties[HttpPropertyKeys.HttpRouteDataKey] = routeData;

             // 4) ControllerContext
             controller.ControllerContext = new HttpControllerContext(config, routeData, request)
             {
                 ControllerDescriptor = new HttpControllerDescriptor(
                     config,
                     routePrefix,
                     controller.GetType())
             };

             // 5) tie Request back onto the controller
             controller.Request = request;

             // 6) extract MethodInfo from the lambda
             if (!(actionExpression.Body is MethodCallExpression mce))
                 throw new ArgumentException("Expression must be a method call", nameof(actionExpression));
             var mi = (MethodInfo)mce.Method;

             // 7) ActionContext
             var actionDescriptor = new ReflectedHttpActionDescriptor
             {
                 ControllerDescriptor = controller.ControllerContext.ControllerDescriptor,
                 MethodInfo = mi
             };
             controller.ActionContext = new HttpActionContext(controller.ControllerContext, actionDescriptor);
         }
     }
 }
