                 if (!Version.TryParse(await this.eceClient.GetStampVersion(), out stampVersion))
                 {
                     stampVersion = new Version();
                 }

                 Version oemVersion;
                 if (!Version.TryParse(await this.eceClient.GetOemVersion(), out oemVersion))
                 {
                     oemVersion = new Version();
                 }

                 var availableUpdates = updates
                     .Where(x => x.State != UpdateState.Installed && x.State != UpdateState.Obsolete)
                     .ToArray();
                 var lastUpdatedTime = updates
                         .Where(x => x.State == UpdateState.Installed)
                         .OrderBy(x => x.InstalledDate)
                         .LastOrDefault()
                         ?.InstalledDate;

                 location = new UpdateLocation(LocationName, null)
                 {
                     State = RegionUpdateState.Unknown,
                     CurrentVersion = stampVersion,
                     CurrentSbeVersion = oemVersion,
                     LastChecked = await this.updateDiscoveryManager.GetLastUpdateDiscoveryTime(),
                     SbeFamily = this.eceClient.GetOemFamily().Result,
                     HardwareModel = this.eceClient.GetHardwareOemModel().Result,
                     PackageVersions = this.eceClient.GetPackageVersions().Result?.Select(t =>
                                         new PackageVersionInfo
                                         {
                                             PackageType = t.Key,
                                             Version = t.Value,
                                             LastUpdated = GetLastUpdateTime(t.Key, updates)
                                         }).ToList(),
                     LastUpdated = lastUpdatedTime
                 };

                 if (availableUpdates.Length > 0)
                 {
                     var metadataOnlyResolverContext = ResolverContextHelpers.GetAllUpdateRunsWithMetadataOnlyContext();

                     // Update runs are returned in descending order by time started.
                     var allUpdateRuns = (await this.updateRunAggregator.GetAllResults(metadataOnlyResolverContext, cancel))?.ToList() ?? new List<UpdateRun>();

                     var updateRuns = allUpdateRuns.GroupBy(x => x.RpId.Parent).ToDictionary(x => x.Key, Enumerable.ToArray);

                     // Get the status of all available updates. Select many will not work because it does not support async calls.
                     foreach (var availableUpdate in availableUpdates.Where(x => updateRuns.ContainsKey(x.RpId)))
                     {
                         var associatedUpdateRuns = updateRuns[availableUpdate.RpId];
                         if (associatedUpdateRuns.Any(x => x.State == UpdateRunState.InProgress))
                         {
                             // If any of the available updates is in progress, then the environment state is in progress. Therefore, we can exit
                             // the loop immediately.
                             location.State = RegionUpdateState.UpdateInProgress;
                             break;
                         }

                         if (availableUpdate.State == UpdateState.ReadyToInstall)
                         {
                             // Do not consider runs for ReadyToInstall updates as they are completed.
                             continue;
                         }

                         // If the update is not in progress but has runs, then all runs must have failed, otherwise the update state would
                         // have transitioned to installed.
                         location.State = associatedUpdateRuns.Last().OnCompleteActionSuccess
                             ? RegionUpdateState.NeedsAttention
                             : RegionUpdateState.UpdateFailed;
                     }

                     // PreparationInProgress
                     if ((location.State == RegionUpdateState.Unknown || location.State == RegionUpdateState.UpdateInProgress) &&
                         availableUpdates.Any(x => x.State == UpdateState.Preparing      ||
                                                   x.State == UpdateState.HealthChecking ||
                                                   x.State == UpdateState.Downloading))
                     {
                         location.State = RegionUpdateState.PreparationInProgress;
                     }

