         /// within a specified timeout, it will return the stale resource list.
         /// </para>
         /// </remarks>
         /// <returns>Information on the retrieved resource list. The returned object also contains whether there
         /// was any error getting the resource list from external components.</returns>
         Task<IEnumerable<T>> GetResourceList(CancellationToken cancel = default);
