+        private static GeneratedCertificateChain CreateMicrosoftCodeSigningChain(string intermediateSubject)
+        {
+            var root = CreateCertificateAuthority(
+                "CN=Microsoft Root Certificate Authority 2011, O=Microsoft Corporation, L=Redmond, S=Washington, C=US",
+                pathLengthConstraint: 1);
+
+            var intermediate = CreateCertificateAuthority(
+                intermediateSubject,
+                issuerCertificate: root,
+                pathLengthConstraint: 0);
+
+            var leaf = CreateLeafCertificate(
+                "CN=Microsoft Corporation, O=Microsoft Corporation, C=US",
+                intermediate.Certificate);
+
+            return new GeneratedCertificateChain(root, intermediate, leaf);
+        }
