+        private static GeneratedCertificate CreateCertificateAuthority(
+            string subject,
+            GeneratedCertificate issuerCertificate = null,
+            int pathLengthConstraint = 0)
+        {
+            var key = RSA.Create(2048);
+            var request = new CertificateRequest(
+                subject,
+                key,
+                HashAlgorithmName.SHA256,
+                RSASignaturePadding.Pkcs1);
+
+            request.CertificateExtensions.Add(
+                new X509BasicConstraintsExtension(
+                    certificateAuthority: true,
+                    hasPathLengthConstraint: true,
+                    pathLengthConstraint: pathLengthConstraint,
+                    critical: true));
+            request.CertificateExtensions.Add(
+                new X509KeyUsageExtension(
+                    X509KeyUsageFlags.KeyCertSign | X509KeyUsageFlags.CrlSign,
+                    critical: true));
+            request.CertificateExtensions.Add(new X509SubjectKeyIdentifierExtension(request.PublicKey, false));        
+
+            var notBefore = DateTimeOffset.UtcNow.AddMinutes(-5);
+            var notAfter = DateTimeOffset.UtcNow.AddDays(1);
+
+            X509Certificate2 certificate;
+            if (issuerCertificate == null)
+            {
+                certificate = request.CreateSelfSigned(notBefore, notAfter);
+            }
+            else
+            {
+                (notBefore, notAfter) = GetChildCertificateValidity(issuerCertificate.Certificate);
+                certificate = request.Create(
+                    issuerCertificate.Certificate,
+                    notBefore,
+                    notAfter,
+                    CreateSerialNumber());
+            }
+
+            using (certificate)
+            {
+                if (issuerCertificate == null)
+                {
+                    return new GeneratedCertificate(ExportCertificate(certificate), key);
+                }
+
+                using var certificateWithPrivateKey = certificate.CopyWithPrivateKey(key);
+                return new GeneratedCertificate(ExportCertificate(certificateWithPrivateKey), key);
+            }
