 namespace Microsoft.AzureStack.Services.Update.ResourceProvider.UpdateService.Security
 {
     using System.Collections.Generic;
     using System.Linq;
     using System.Security.Cryptography.X509Certificates;
     using System.Text.RegularExpressions;
     using Microsoft.AzureStack.Services.Update.ResourceProvider.UpdateService.Security.Logger;

     /// <summary>
     /// Default certificate validator that checks if the signing certificate is valid.
     /// </summary>
     public class DefaultCertificateValidator : ICertificateValidator
     {
         private ISignedXMLEventLogger signedXMLEventLogger;

         /// <summary>
         /// Constructor for the <see cref="DefaultCertificateValidator"/> class.
         /// </summary>
         /// <param name="signedXMLEventLogger"></param>
         public DefaultCertificateValidator(ISignedXMLEventLogger signedXMLEventLogger)
         {
             this.signedXMLEventLogger = signedXMLEventLogger;
         }

         /// <inheritdoc />
         public bool ValidateSigningCertificate(X509Certificate2 signingCert, ICollection<X509Certificate2> certChainFromMetadataXml)
         {
             if (ValidateCertificateChain(signingCert, certChainFromMetadataXml))
             {
                 signedXMLEventLogger.XmlSigningCertValidatedUsingChain(signingCert);
                 return true;
             }

             signedXMLEventLogger.XmlSigningCertNotValid(signingCert);
             return false;
         }

         private bool ValidateCertificateChain(X509Certificate2 signingCertificate, ICollection<X509Certificate2> certChainFromMetadataXml)
         {
             if (!certChainFromMetadataXml.Contains(signingCertificate))
             {
                 return false;
             }

             var certChain = new X509Chain(true) // Pass true to use the machine store because GMSA doesn't have a user profile.
             {
                 ChainPolicy = new X509ChainPolicy
                 {
                     VerificationFlags = X509VerificationFlags.IgnoreNotTimeValid,
                     RevocationMode = X509RevocationMode.NoCheck
                 }
             };

             certChain.ChainPolicy.ExtraStore.AddRange(certChainFromMetadataXml.ToArray());
             certChain.Build(signingCertificate);

             if (!ValidateCertificateChainsAreEqual(certChainFromMetadataXml, certChain))
             {
                 signedXMLEventLogger.XmlSigningCertChainNotEquivalentToBuiltChain(signingCertificate);
                 return false;
             }

             const string issuerPattern = @"^CN=Microsoft Code Signing PCA(?:\s+\d{4})?,\s*O=Microsoft Corporation(?:,\s*[^=]+=[^,]+)*$";

             if (!Regex.IsMatch(signingCertificate.Issuer, issuerPattern, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant))
             {
                 signedXMLEventLogger.XmlSignedWithNonMicrosoftCert(signingCertificate);
                 return false;
             }

             return true;
         }

         private static bool ValidateCertificateChainsAreEqual(ICollection<X509Certificate2> certChainFromMetadataXml, X509Chain chainFromBuild)
         {
             if (certChainFromMetadataXml.Count != chainFromBuild.ChainElements.Count)
             {
                 return false;
             }

             foreach (var chainElement in chainFromBuild.ChainElements)
             {
                 var cert = chainElement.Certificate;
                 if (!certChainFromMetadataXml.Contains(cert))
                 {
                     return false;
                 }
             }

             return true;
         }
     }
 }


