7. namespace Microsoft.AzureStack.Services.Update.ResourceProvider.UpdateService.Controllers.Helpers
8. {
9.     using System;
10.     using System.Collections.Concurrent;
11.     using System.Globalization;
12.     using System.Net;
13.     using System.Net.Http;
14.     using System.Threading;
15.     using System.Threading.Tasks;
16. 
17.     /// <summary>
18.     /// A delegating handler that enforces per-client circuit breaker semantics for UpdateLocation GET requests.
19.     /// When a client (identified by User-Agent header) already has an in-flight request to the UpdateLocation
20.     /// endpoint, subsequent requests from the same client are rejected with 429 Too Many Requests.
21.     /// Clients without a User-Agent header are grouped under a single default identity.
22.     /// </summary>
23.     public class PerClientCircuitBreakerHandler : DelegatingHandler
24.     {
25.         /// <summary>
26.         /// The default client identifier used when the User-Agent header is missing or empty.
27.         /// </summary>
28.         internal const string DefaultClientIdentifier = "unknown";
29. 
30.         /// <summary>
31.         /// The URL segment that identifies UpdateLocation resource routes.
32.         /// </summary>
33.         internal const string UpdateLocationRouteSegment = "updateLocations";
34. 
35.         private readonly ConcurrentDictionary<string, SemaphoreSlim> clientGates =
36.             new ConcurrentDictionary<string, SemaphoreSlim>(StringComparer.OrdinalIgnoreCase);
37. 
38.         /// <inheritdoc />
39.         protected override async Task<HttpResponseMessage> SendAsync(
40.             HttpRequestMessage request,
41.             CancellationToken cancellationToken)
42.         {
43.             if (!IsUpdateLocationGetRequest(request))
44.             {
45.                 return await base.SendAsync(request, cancellationToken).ConfigureAwait(false);
46.             }
47. 
48.             string clientId = GetClientIdentifier(request);
49.             var gate = this.clientGates.GetOrAdd(clientId, _ => new SemaphoreSlim(1, 1));
50. 
51.             if (!await gate.WaitAsync(0).ConfigureAwait(false))
52.             {
53.                 return CreateCircuitBreakerResponse(request, clientId);
54.             }
55. 
