73.             if (request.Method != HttpMethod.Get)
74.             {
75.                 return false;
76.             }
77. 
78.             var path = request.RequestUri.AbsolutePath;
79.             var segments = path.Split(new[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
