     using System.Collections.Concurrent;
     using System.Globalization;
     using System.Net;
     using System.Net.Http;
     using System.Threading;
     using System.Threading.Tasks;

     /// <summary>
     /// A delegating handler that enforces per-client circuit breaker semantics for UpdateLocation GET requests.
     /// When a client (identified by User-Agent header) already has an in-flight request to the UpdateLocation
     /// endpoint, subsequent requests from the same client are rejected with 429 Too Many Requests.
     /// Clients without a User-Agent header are grouped under a single default identity.
     /// </summary>
     public class PerClientCircuitBreakerHandler : DelegatingHandler
     {
         /// <summary>
         /// The default client identifier used when the User-Agent header is missing or empty.
         /// </summary>
         internal const string DefaultClientIdentifier = "unknown";

         /// <summary>
         /// The URL segment that identifies UpdateLocation resource routes.
         /// </summary>
         internal const string UpdateLocationRouteSegment = "updateLocations";

         private readonly ConcurrentDictionary<string, SemaphoreSlim> clientGates =
             new ConcurrentDictionary<string, SemaphoreSlim>(StringComparer.OrdinalIgnoreCase);

         /// <inheritdoc />
         protected override async Task<HttpResponseMessage> SendAsync(
             HttpRequestMessage request,
             CancellationToken cancellationToken)
         {
             if (!IsUpdateLocationGetRequest(request))
             {
                 return await base.SendAsync(request, cancellationToken).ConfigureAwait(false);
             }

             string clientId = GetClientIdentifier(request);
             var gate = this.clientGates.GetOrAdd(clientId, _ => new SemaphoreSlim(1, 1));

             if (!await gate.WaitAsync(0).ConfigureAwait(false))
             {
                 return CreateCircuitBreakerResponse(request, clientId);
             }

             try
             {
                 return await base.SendAsync(request, cancellationToken).ConfigureAwait(false);
             }
             finally
             {
                 gate.Release();
             }
         }

         /// <summary>
         /// Determines whether the request is a GET request targeting the UpdateLocation resource.
         /// Only matches top-level UpdateLocation paths (e.g., .../updateLocations or .../updateLocations/{name}),
         /// not nested resources (e.g., .../updateLocations/{name}/updates/...).
         /// </summary>
         internal static bool IsUpdateLocationGetRequest(HttpRequestMessage request)
         {
             if (request.Method != HttpMethod.Get)
             {
                 return false;
             }

             var path = request.RequestUri.AbsolutePath;
             var segments = path.Split(new[] { '/' }, StringSplitOptions.RemoveEmptyEntries);

             for (int i = 0; i < segments.Length; i++)
             {
                 if (string.Equals(segments[i], UpdateLocationRouteSegment, StringComparison.OrdinalIgnoreCase))
                 {
                     // updateLocations is the last segment (list) or followed by exactly one segment (get by name)
                     int remainingSegments = segments.Length - i - 1;
                     return remainingSegments <= 1;
                 }
             }

             return false;
         }

